"""Cuaderno del estudiante, 5.º básico Lenguaje y Comunicación, OA 05 (imágenes, figuras y forma poética).

Todos los poemas son originales y breves, escritos para este cuaderno; los poemas de autores reales quedan para el docente.
En los poemas, « / » separa versos y « // » separa estrofas.
"""
from __future__ import annotations

from student_content_le5_a import E, L, n_words
from student_lessons import arith

OA5 = "LE05 OA 05"

MANANA = "Huele a pan la mañana tibia, / canta el río entre las piedras, / la niebla es un manto suave / que abriga la hierba quieta."
TARDE = "La tarde se fue callando, / las nubes se hicieron grises, / y yo, sentado en la puerta, / esperé sin decir nada."
RISA = "Salta la risa en el patio / y el sol se pone a bailar; / todo el día es una fiesta / y no quiero que se acabe."
SOMBRA = "La noche cruje en la casa, / una sombra se agranda en la pared; / contengo el aliento / y no me atrevo a moverme."
VIENTO = "El viento toca a mi puerta / y pide un poco de pan; / la lluvia lava las calles / y se echa a descansar."
MANOS = "Tus manos son como pájaros / que vuelan sobre el papel; / tu risa, igual que la luna, / ilumina mi pared."
HUERTO = "En el huerto de mi abuela / canta un grillo al anochecer; / las estrellas se despiertan / y el jardín se echa a crecer. // Bajo el árbol de la plaza / duerme un perro sin cuidado; / las hojas caen despacio / sobre el suelo ya dorado. // Llega el sueño a mi ventana / con un cuento de papel; / y yo, cerrando los ojos, / sueño un mundo de miel."
LLUVIA = "La lluvia teje en el techo / una canción de cristal; / las gotas, como campanas, / llaman al sueño a pasar. // El silencio se acurruca / junto a la manta de lana; / afuera, la noche inmensa / se duerme sobre la montaña."


def n_versos(poema):
    return str(len(poema.replace(" // ", " / ").split(" / ")))


def n_estrofas(poema):
    return str(len(poema.split(" // ")))


L(OA5, 1,
  "Este cuaderno, lápiz y los poemas escritos en esta clase.",
  "Aprenderé a explicar cómo el lenguaje poético apela a los sentidos y crea imágenes en la mente del lector.",
  ["Sé qué es un verso.", "Conozco los cinco sentidos."],
  ["Un poema usa las palabras para que sintamos y veamos cosas, no solo para informar. Muchas veces apela a los sentidos: vista, oído, olfato, gusto y tacto. Cuando un verso dice «Huele a pan la mañana», no solo nos cuenta algo: nos hace sentir un olor.",
   "Una imagen poética es lo que el verso nos hace ver, oír, oler, saborear o tocar en la imaginación. Por eso, para comprender un poema, conviene detenerse en cada verso y preguntarse: ¿qué imagino? ¿A qué sentido apela? Dos lectores pueden imaginar cosas algo distintas, pero deben apoyarse en las palabras del poema.",
   "El poeta elige palabras que despiertan sensaciones: «tibia», «suave» y «quieta» nos dan sensaciones de tacto y calma. Cuando explicas un poema, nombra el sentido, cita el verso y di qué imagen te crea."],
  [("lenguaje poético", "uso de las palabras para crear imágenes y emociones"), ("imagen poética", "lo que un verso nos hace imaginar con los sentidos"), ("sentidos", "vista, oído, olfato, gusto y tacto"), ("sensación", "lo que se percibe con un sentido")],
  [("Hallar el sentido", f"Poema: «{MANANA}» ¿A qué sentido apela «canta el río entre las piedras»?", ["Pienso en el sonido del río.", "Oír es el sentido del oído.", "El verso apela al oído."], "Al oído"),
   ("Explicar la imagen", "¿Qué imagen crea «la niebla es un manto suave»?", ["Un manto es una tela que cubre.", "La niebla cubre el paisaje como un manto suave.", "Imagino una niebla delicada que lo envuelve todo."], "Una niebla suave que cubre todo")],
  [("Decir que el poema solo cuenta cosas.", "Se lee como un texto informativo.", "Fíjate en lo que sientes e imaginas."), ("Citar un verso sin explicar el sentido.", "Se cree que basta copiar.", "Nombra el sentido y explica la imagen.")],
  ([E("¿Qué sentido apela «Huele a pan la mañana tibia»: el olfato o la vista?", "El olfato", "«Huele» habla de un olor."),
    E("¿Con qué sentido percibes un sonido: el oído o el gusto?", "El oído", "El oído capta sonidos."),
    E("¿Con qué sentido percibes que algo es suave: el tacto o el olfato?", "El tacto", "Lo suave se siente al tocar.")],
   [E(MANANA + " Según el poema de la mañana, ¿qué hace el río entre las piedras?", "Canta", "Así lo dice el segundo verso."),
    E("Con «la niebla es un manto suave», ¿qué sensación se da: de frío cortante o de cobijo suave?", "De cobijo suave", "Un manto suave abriga."),
    E("¿Qué es una imagen poética: lo que un verso nos hace imaginar o un dibujo hecho con lápiz?", "Lo que un verso nos hace imaginar", "Es una imagen en la mente.")],
   [E("En «La miel dulce se derrite en mi lengua», ¿qué sentido se apela?", "El gusto", "Habla de un sabor dulce."),
    E("En «Las luces rojas brillan en la noche», ¿qué sentido se apela?", "La vista", "Se ven luces rojas y brillantes."),
    E("En «Suena una campana lejana», ¿qué sentido se apela?", "El oído", "Se escucha un sonido.")],
   [E("Ana dice que en «Huele a pan la mañana tibia» hay olfato y tacto. Beto, que solo hay tacto. ¿Quién tiene razón?", "Ana", "«Huele» es olfato y «tibia» es tacto."),
    E("Si un poema dice «el aire pica de tan frío», ¿qué sensación quiere crear: frío intenso o calor?", "Frío intenso", "«Pica de tan frío» exagera el frío.")],
   [E("¿Cuántos sentidos distintos hay en: «Huele a pan la mañana tibia, / canta el río entre las piedras»?", "3", "Olfato (huele), tacto (tibia) y oído (canta)."),
    E("Un poema dice «El limón agrio me arruga la boca». ¿Qué sentido apela?", "El gusto", "Habla de un sabor agrio.")]),
  [E("Quieres escribir un verso que haga sentir la lluvia con el oído. ¿Qué palabra elegirías: «tamborilea» o «brilla»?", "Tamborilea", "Imita el sonido de golpecitos.")],
  [E("¿Cuáles son los cinco sentidos?", "Vista, oído, olfato, gusto y tacto", "Son las formas de percibir."),
   E("¿Qué es el lenguaje poético?", "El que usa las palabras para crear imágenes y emociones", "No solo informa."),
   E("Para explicar una imagen, ¿qué haces: nombras el sentido y dices lo que imaginas, o copias el verso sin comentarlo?", "Nombro el sentido y digo lo que imagino", "Así explicas cómo funciona el verso.")],
  (f"Lee el poema: «{MANANA}» Escribe: 1) los sentidos que reconoces; 2) un verso que apele a cada uno; 3) dibuja o describe la escena que imaginas.", "1) Olfato, oído, tacto. 2) «Huele a pan…» (olfato); «canta el río…» (oído); «manto suave» (tacto). 3) Una mañana de pueblo con niebla suave y un río cantando.", ["identifica sentidos", "cita un verso por sentido", "describe la imagen que crea"], ["tres sentidos con versos", "descripción"], ["no relacionar con el verso", "describir lo que no dice el poema"], "Compara tu escena con la de otra persona y busca en qué versos se basa cada una."),
  "Lee un poema y marca con colores los versos que apelan a cada sentido.",
  "Escribe dos versos sobre tu casa por la mañana que apelen al olfato y al oído.")

L(OA5, 2,
  "Este cuaderno, lápiz y los poemas escritos en esta clase.",
  "Aprenderé a explicar cómo un poema sugiere estados de ánimo, como alegría, tristeza, calma o miedo, a partir de sus palabras.",
  ["Reconozco imágenes que apelan a los sentidos.", "Conozco palabras para sentimientos."],
  ["Un estado de ánimo es cómo se siente una persona en un momento: alegre, triste, tranquila, asustada. Un poema no siempre dice el sentimiento con todas sus letras: lo sugiere con imágenes, palabras y ritmo. El lector lo descubre mirando qué palabras elige el poeta.",
   "Hay palabras que dan pistas. «Callando», «grises» y «esperé sin decir nada» sugieren una tristeza callada. «Salta», «bailar» y «fiesta» sugieren alegría. «Cruje», «sombra» y «contengo el aliento» sugieren miedo. También cuentan los colores, los sonidos y los movimientos lentos o rápidos.",
   "Para explicar un estado de ánimo, escribe: «El poema transmite ___ porque dice ___». Así muestras cuál es la sensación y cuál es la pista. Puede haber más de una lectura, siempre que se apoye en el texto."],
  [("estado de ánimo", "cómo se siente alguien en un momento"), ("sugerir", "dar a entender algo sin decirlo directamente"), ("pista", "dato del texto que ayuda a descubrir algo"), ("tono", "actitud o sentimiento que transmite un poema")],
  [("Descubrir un estado de ánimo", f"Poema: «{TARDE}» ¿Qué estado de ánimo transmite?", ["Veo palabras como «callando», «grises» y «sin decir nada».", "Sugieren silencio y tristeza.", "El poema transmite tristeza o nostalgia tranquila."], "Tristeza o nostalgia"),
   ("Explicar con pistas", f"Poema: «{RISA}» ¿Cómo lo explicas?", ["Digo el estado de ánimo: alegría.", "Cito pistas: «salta la risa», «bailar», «fiesta».", "Concluyo: transmite alegría porque habla de risa y baile."], "Transmite alegría porque habla de risa, baile y fiesta")],
  [("Decir el sentimiento sin dar pistas.", "Se cree que es obvio.", "Cita palabras del poema."), ("Pensar que el poema debe nombrar el sentimiento.", "Se busca la palabra «triste».", "El poeta lo sugiere con imágenes.")],
  ([E("¿Qué estado de ánimo sugiere «Salta la risa en el patio»: alegría o miedo?", "Alegría", "Saltar y reír son señales de alegría."),
    E("¿Qué palabra de «La tarde se fue callando» sugiere silencio?", "callando", "Indica que la tarde se hace silenciosa."),
    E("¿Qué sugiere «contengo el aliento»: miedo o alegría?", "Miedo", "Quien contiene el aliento está asustado o atento.")],
   [E("¿Qué estado de ánimo sugieren los colores grises en «las nubes se hicieron grises»: tristeza o entusiasmo?", "Tristeza", "El gris suele asociarse a tristeza."),
    E("En el poema del miedo, ¿qué pista muestra el miedo: «una sombra se agranda en la pared» o «el sol se pone a bailar»?", "«una sombra se agranda en la pared»", "La sombra que crece da miedo."),
    E("¿El poeta debe escribir la palabra «tristeza» para transmitirla?", "No", "Puede sugerirla con imágenes.")],
   [E(f"Poema: «{SOMBRA}» ¿Qué estado de ánimo transmite?", "Miedo", "Hay una sombra que crece y el hablante contiene el aliento."),
    E(f"Poema: «{TARDE}» ¿Qué hacía el hablante en la puerta?", "Esperaba sin decir nada", "Lo dice el último verso."),
    E(RISA + " Completa: «El poema de la risa transmite alegría porque dice ___».", "«salta la risa» y «el sol se pone a bailar»", "Son pistas de alegría.")],
   [E("Ana dice que «Esperé sin decir nada» sugiere impaciencia gritona. Beto, que sugiere calma triste. ¿Quién se apoya mejor en el texto?", "Beto", "«Sin decir nada» indica silencio."),
    E("Un lector dice que «La tarde se fue callando» transmite calma. Otro, tristeza. ¿Pueden ser lecturas válidas si ambas se apoyan en el texto?", "Sí", "Un poema puede sugerir más de un sentimiento.")],
   [E("Si cambias «grises» por «doradas» en «las nubes se hicieron grises», ¿el poema sería más triste o menos triste?", "Menos triste", "El dorado sugiere luz y calidez."),
    E(SOMBRA + " ¿Qué palabra del poema da una pista de oscuridad: «noche» o «pared»?", "Noche", "Las noches son oscuras; una pared no lo es por sí sola.")]),
  [E("En un cumpleaños escribes: «Las velas bailan y el mundo se llena de música». ¿Qué estado de ánimo transmite?", "Alegría", "Bailar y la música sugieren fiesta.")],
  [E("¿Qué es un estado de ánimo?", "Cómo se siente alguien en un momento", "Puede ser alegría, tristeza o miedo."),
   E("¿Cómo se descubre en un poema?", "Con las pistas de sus palabras", "El poeta lo sugiere."),
   E("¿Qué se escribe para explicarlo?", "El sentimiento y la pista que lo muestra", "Así queda fundamentado.")],
  (f"Lee: «{TARDE}» y «{RISA}» Escribe, para cada poema, el estado de ánimo, dos pistas del texto y un cambio de una palabra que modificaría el sentimiento.", "Tarde: tristeza; pistas «callando» y «grises»; cambiar «grises» por «doradas». Risa: alegría; pistas «salta la risa» y «bailar»; cambiar «bailar» por «dormir» hace el poema más calmado.", ["nombra el estado de ánimo", "cita dos pistas por poema", "propone un cambio coherente"], ["dos análisis"], ["no citar pistas", "cambiar sin explicar"], "Lee tus pistas a otra persona y pregúntale si coincide con el sentimiento."),
  "Lee un poema y escribe una frase: «El poema transmite ___ porque dice ___».",
  "Escribe cuatro versos con un estado de ánimo y tres pistas que lo sugieran.")

L(OA5, 3,
  "Este cuaderno, lápiz y los poemas escritos en esta clase.",
  "Aprenderé a identificar personificaciones en un poema y a explicar qué significan dentro de él.",
  ["Reconozco imágenes y estados de ánimo.", "Sé qué es una figura del lenguaje."],
  ["La personificación es una figura poética que atribuye acciones, sentimientos o rasgos humanos a cosas, animales o fenómenos que no son personas. Cuando un poema dice «El viento toca a mi puerta», el viento no tiene manos; lo que hace es golpear la puerta con fuerza, y el poeta lo muestra como una visita.",
   "Para reconocerla, busca un sujeto que no sea persona, como el sol, la luna o la lluvia, y un verbo que solo hacen las personas, como hablar, pedir, abrazar o dormir. Luego pregúntate qué quiere decir el poeta: «la lluvia lava las calles» sugiere que el agua limpia las calles, como una persona que hace aseo.",
   "Para explicar su significado dentro del poema, escribe: «La personificación ___ muestra que ___». Por ejemplo: «El viento pide pan» muestra un viento que llega con frío y parece necesitar abrigo. No basta con decir que es una personificación: hay que explicar qué efecto produce."],
  [("personificación", "figura que da rasgos humanos a lo que no es persona"), ("sujeto", "quien o qué realiza la acción de una oración"), ("figura poética", "recurso con que el poeta da más fuerza a lo que dice"), ("significado", "lo que quiere decir algo")],
  [("Reconocer la personificación", f"Poema: «{VIENTO}» ¿Qué verso personifica al viento?", ["Busco una acción humana del viento.", "«toca a mi puerta y pide un poco de pan» son acciones de personas.", "Ahí está la personificación."], "El viento toca a mi puerta y pide pan"),
   ("Explicar el significado", "¿Qué significa «la lluvia se echa a descansar»?", ["Echarse a descansar es algo humano.", "Dice que la lluvia se detiene.", "Significa que dejó de llover."], "Que la lluvia terminó")],
  [("Decir que toda acción de la naturaleza es personificación.", "Se confunde con describir.", "Solo es personificación si la acción es propia de personas."), ("Reconocerla sin explicar su efecto.", "Se cree que basta nombrar la figura.", "Explica qué muestra en el poema.")],
  ([E("En «El viento toca a mi puerta», ¿qué hace el viento como si fuera persona?", "Toca a la puerta", "Tocar a la puerta es propio de personas."),
    E("¿La personificación da rasgos humanos a las personas o a las cosas?", "A las cosas", "Atribuye lo humano a lo que no es persona."),
    E("En «La lluvia lava las calles», ¿quién realiza la acción?", "La lluvia", "Es el sujeto del verbo.")],
   [E("¿«El perro ladra a la puerta» es personificación?", "No", "Ladrar es algo que hacen los perros."),
    E("¿«La luna sonríe» es personificación?", "Sí", "Sonreír es propio de personas."),
    E(VIENTO + " En el poema, ¿qué pide el viento?", "Un poco de pan", "Lo dice el segundo verso.")],
   [E("«La lluvia se echa a descansar» significa que: (a) la lluvia terminó o (b) la lluvia se durmió en un sillón.", "(a)", "Describe que dejó de llover."),
    E("En «Las estrellas se despiertan», ¿qué acción humana se atribuye a las estrellas?", "Despertarse", "Despertarse es propio de personas."),
    E("Subraya el verbo humano: «El sol saluda a la montaña».", "Saluda", "Saludar es una acción de personas.")],
   [E("Ana dice que «El viento toca a mi puerta» muestra un viento fuerte. Beto, que muestra a un amigo visitando. ¿Quién da una interpretación posible?", "Ambos", "La figura puede transmitir fuerza y compañía."),
    E("¿Por qué el poeta personifica al viento en lugar de decir «hacía viento»: para crear una imagen más viva o porque no sabía describirlo?", "Para crear una imagen más viva", "La personificación da fuerza al verso.")],
   [E("Escribe el sujeto no humano de «La noche se acurruca junto a mí».", "La noche", "Realiza una acción humana."),
    E("¿Qué muestra la personificación «el sol se pone a bailar»: que el sol parece alegre y en movimiento o que el sol se apagó?", "Que el sol parece alegre y en movimiento", "Bailar sugiere alegría y movimiento.")]),
  [E("En un cuaderno de poemas, un niño escribe: «Mi bufanda me abraza en el invierno». ¿Qué acción humana tiene la bufanda?", "Abrazar", "Abrazar es propio de personas.")],
  [E("¿Qué es una personificación?", "Dar rasgos humanos a lo que no es persona", "Es una figura poética."),
   E("¿Basta con nombrar la figura?", "No, hay que explicar qué muestra", "Se debe explicar su efecto."),
   E("¿«La lluvia golpea el techo» es personificación?", "No", "Golpear puede hacerlo la lluvia.")],
  (f"Lee: «{VIENTO}» Escribe: 1) dos de las personificaciones del poema (hay tres); 2) qué significa cada una; 3) una personificación propia sobre el mar.", "1) «El viento toca a mi puerta y pide pan» y «la lluvia se echa a descansar» (otra es «la lluvia lava las calles»). 2) El viento llega fuerte y frío; la lluvia termina. 3) El mar duerme tranquilo bajo la luna.", ["identifica dos personificaciones", "explica su significado", "crea una propia"], ["tres respuestas"], ["nombrar sin explicar", "confundir con acciones propias"], "Pide a alguien que busque la acción humana en tu personificación."),
  "Busca en un poema una personificación y explica su significado.",
  "Escribe tres versos con personificaciones sobre un amanecer.")

L(OA5, 4,
  "Este cuaderno, lápiz y los poemas escritos en esta clase.",
  "Aprenderé a identificar comparaciones en un poema y a explicar qué relación establecen entre las cosas comparadas.",
  ["Sé qué es una personificación.", "Conozco «como» e «igual que»."],
  ["La comparación une dos elementos usando palabras como «como», «igual que» o «parecido a». En «Tus manos son como pájaros», se compara las manos con los pájaros. El primer elemento es lo comparado, y el segundo, con lo que se compara. Se comparan porque tienen algo en común.",
   "Para explicar una comparación, busca el rasgo compartido. Las manos y los pájaros comparten ligereza y movimiento: las manos vuelan sobre el papel. Así, la comparación nos hace imaginar manos ágiles y delicadas. En «tu risa, igual que la luna, ilumina», la risa y la luna comparten luz.",
   "No todas las palabras «como» forman comparaciones: en «como pan» (verbo comer) no hay comparación. Debe unir dos cosas distintas con un rasgo en común. Al explicarla, escribe: «Compara ___ con ___ porque ambos ___»."],
  [("comparación", "figura que une dos cosas con «como», «igual que» o «parecido a» por un rasgo común"), ("rasgo común", "característica que comparten dos cosas"), ("nexo", "palabra que une, como «como» en una comparación"), ("ágil", "que se mueve con rapidez y soltura")],
  [("Reconocer la comparación", f"Poema: «{MANOS}» ¿Qué verso es una comparación?", ["Busco «como» o «igual que».", "«Tus manos son como pájaros» une manos y pájaros.", "También «tu risa, igual que la luna»."], "«Tus manos son como pájaros» y «tu risa, igual que la luna»"),
   ("Explicar el rasgo común", "¿Qué comparten la risa y la luna en «tu risa, igual que la luna, ilumina mi pared»?", ["La luna ilumina.", "La risa, según el poema, ilumina también.", "Comparten la luz."], "Que iluminan")],
  [("Creer que toda palabra «como» forma una comparación.", "No se miran los elementos.", "Debe unir dos cosas distintas por un rasgo en común."), ("No decir cuál es el rasgo común.", "Se piensa que es evidente.", "Explica qué comparten.")],
  ([E("En «Tus manos son como pájaros», ¿qué dos cosas se comparan?", "Las manos y los pájaros", "Une manos con pájaros."),
    E("¿Qué palabra une los elementos de una comparación en «igual que la luna»?", "Igual que", "Es el nexo."),
    E("«Corre como el viento». ¿Es comparación?", "Sí", "Une correr con el viento mediante «como».")],
   [E(MANOS + " ¿Qué comparten las manos y los pájaros en el poema: el vuelo ligero o el color?", "El vuelo ligero", "Las manos «vuelan» sobre el papel."),
    E("«Yo como manzana» ¿es comparación?", "No", "«Como» es el verbo comer."),
    E(MANOS + " ¿Qué comparte la risa con la luna según el poema?", "Ilumina", "El último verso lo dice.")],
   [E("«Tu mirada es tan profunda como el mar». ¿Qué rasgo común destaca: la profundidad o el color?", "La profundidad", "Dice «tan profunda»."),
    E("«El niño lloró igual que una cascada». ¿Qué se compara con la cascada?", "El llanto del niño", "Se compara cómo lloraba."),
    E("Subraya el nexo: «La nieve, parecida a una manta, cubrió el campo».", "Parecida a", "Es la palabra que compara.")],
   [E("Ana dice que «tus manos son como pájaros» destaca la velocidad. Beto, la ligereza y delicadeza. ¿Quién se apoya mejor en «vuelan sobre el papel»?", "Beto", "«Vuelan» sugiere ligereza."),
    E("¿Por qué comparar la risa con la luna: para destacar que ilumina o porque tienen el mismo tamaño?", "Para destacar que ilumina", "El verso dice «ilumina mi pared».")],
   [E("¿Qué comparación tiene sentido para un perro veloz: (a) «El perro corre como una flecha» o (b) «El perro corre como una mesa»?", "(a)", "Una flecha es veloz, como se quiere destacar."),
    E("«La noche es tan oscura como boca de lobo». ¿Qué rasgo se destaca?", "Que está muy oscura", "El rasgo común es la oscuridad.")]),
  [E("Un niño describe a su hermana: «Es alegre como un cascabel». ¿Qué rasgo destaca?", "Que es alegre", "El cascabel suena alegre.")],
  [E("¿Con qué palabras se hace una comparación?", "Con «como», «igual que» o «parecido a»", "Son nexos de comparación."),
   E("¿Qué debe haber entre las cosas comparadas?", "Un rasgo común", "Por eso se comparan."),
   E("¿La comparación y la personificación son lo mismo?", "No", "La primera une dos cosas; la segunda da rasgos humanos.")],
  (f"Lee: «{MANOS}» Escribe: 1) las dos comparaciones; 2) el rasgo común de cada una; 3) una comparación original sobre tu mascota o un animal.", "1) Manos–pájaros; risa–luna. 2) Ligereza; luz. 3) Mi gato duerme como una bolita de lana (calma).", ["identifica comparaciones", "explica el rasgo común", "crea una comparación"], ["tres respuestas"], ["no explicar el rasgo", "usar «como» sin comparar"], "Explica tu comparación a otra persona y verifica que entienda el rasgo."),
  "Busca en un poema una comparación y explica su rasgo común.",
  "Escribe tres comparaciones sobre la lluvia, el sol y el viento.")

L(OA5, 5,
  "Este cuaderno, lápiz y el poema escrito en esta clase.",
  "Aprenderé a distinguir los versos y las estrofas de un poema y a contarlos.",
  ["Reconozco un poema por sus líneas.", "Cuento en voz alta."],
  ["Un poema se organiza en versos y estrofas. El verso es cada línea del poema. La estrofa es un grupo de versos que forman una unidad y están separados de otro grupo por un espacio en blanco. En este cuaderno, la barra / separa versos y la doble barra // separa estrofas.",
   "Cada estrofa suele tener su propia idea. Una puede hablar del huerto, otra de la plaza y otra del sueño. Contar los versos de cada estrofa permite ver cómo está construido el poema. Hay estrofas de dos, tres, cuatro o más versos, y también poemas con estrofas de distinto largo.",
   "Para contar bien, recorre el poema línea por línea y marca cada verso. Después cuenta cuántos hay en cada estrofa y cuántas estrofas hay. El total de versos es la suma de los versos de todas las estrofas. Un error común es contar las palabras en vez de las líneas."],
  [("verso", "cada línea de un poema"), ("estrofa", "grupo de versos separado de otros"), ("poema", "texto escrito en versos"), ("unidad", "parte que forma un todo con sentido")],
  [("Contar versos y estrofas", f"Poema: «{HUERTO}» ¿Cuántas estrofas tiene?", ["Busco las dobles barras // que separan estrofas.", "Hay dos separaciones.", "Con dos separaciones hay tres estrofas."], "3 estrofas"),
   ("Total de versos", "Si cada una de las 3 estrofas tiene 4 versos, ¿cuántos versos tiene el poema?", ["Cuento los versos por estrofa: 4.", "Hay 3 estrofas.", "Multiplico: 4 × 3 = 12."], "12 versos")],
  [("Contar palabras en lugar de versos.", "Se confunde verso con palabra.", "El verso es una línea completa."), ("Confundir estrofa con verso.", "Se cree que son lo mismo.", "La estrofa es un grupo de versos.")],
  ([E("Las líneas de «La tarde se fue callando, / las nubes se hicieron grises» ¿cómo se llaman?", "Versos", "Las líneas son versos."),
    E("¿Cómo se llama el grupo de versos de un poema?", "Estrofa", "Reúne varios versos."),
    E("¿Cuántos versos tiene «La tarde se fue callando, / las nubes se hicieron grises, / y yo, sentado en la puerta, / esperé sin decir nada.»?", n_versos(TARDE), "Las barras separan cuatro líneas.")],
   [E(HUERTO + " ¿Cuántas estrofas tiene el poema del huerto?", n_estrofas(HUERTO), "Hay dos separaciones //, por lo tanto tres grupos de versos."),
    E(HUERTO + " ¿Cuántos versos tiene la primera estrofa del poema del huerto?", "4", "Comienza en «En el huerto de mi abuela» y termina en «se echa a crecer»."),
    E("¿Qué separa las estrofas en este cuaderno: la barra / o la doble barra //?", "La doble barra //", "La barra simple separa versos.")],
   [E(HUERTO + " ¿Cuántos versos tiene todo el poema del huerto?", n_versos(HUERTO), "Son 3 estrofas de 4 versos."),
    arith("Un poema tiene 5 estrofas de 3 versos cada una. ¿Cuántos versos tiene?", "5*3", "Se multiplican las estrofas por los versos de cada una."),
    E(HUERTO + " ¿Cuál es el último verso del poema del huerto?", "sueño un mundo de miel", "Es el verso final de la tercera estrofa.")],
   [E("Ana dice que «Huele a pan la mañana tibia» tiene 6 versos porque tiene 6 palabras. ¿Está bien?", "No", "El verso es una línea, no una palabra."),
    E("Un poema tiene 8 versos en 2 estrofas iguales. ¿Cuántos versos tiene cada estrofa?", "4", "8 ÷ 2 = 4.")],
   [arith("Un poema tiene 3 estrofas: dos de 4 versos y una de 6 versos. ¿Cuántos versos tiene en total?", "4+4+6", "Se suman los versos de cada estrofa."),
    E(f"Poema: «{LLUVIA}» ¿Cuántos versos y cuántas estrofas tiene?", f"{n_versos(LLUVIA)} versos y {n_estrofas(LLUVIA)} estrofas", "Hay dos grupos de cuatro versos.")]),
  [E("En una antología, el índice dice «Poema de 12 versos en 3 estrofas iguales». ¿Cuántos versos tiene cada estrofa?", "4", "12 ÷ 3 = 4.")],
  [E("En el análisis de un poema, ¿qué es un verso?", "Una línea del poema", "Es la unidad básica."),
   E("En el análisis de un poema, ¿qué es una estrofa?", "Un grupo de versos", "Reúne varios versos juntos."),
   E("¿Se cuentan las palabras para saber cuántos versos hay?", "No", "Se cuentan las líneas.")],
  (f"Lee: «{HUERTO}» Escribe: 1) cuántas estrofas y cuántos versos tiene; 2) de qué trata cada estrofa en una frase; 3) un título que englobe las tres.", "1) 3 estrofas y 12 versos. 2) El huerto de la abuela; la plaza con el perro; el sueño. 3) «Del huerto al sueño».", ["cuenta bien estrofas y versos", "resume cada estrofa", "propone un título pertinente"], ["tres respuestas"], ["contar palabras", "resumir sin leer cada estrofa"], "Pide a alguien que cuente en voz alta contigo y comparen."),
  "Elige un poema de un libro y cuenta sus versos y estrofas.",
  "Escribe un poema de dos estrofas de tres versos sobre un día de verano.")

L(OA5, 6,
  "Este cuaderno, lápiz y las palabras escritas en esta clase.",
  "Aprenderé a distinguir la rima consonante de la rima asonante y a reconocerlas en un poema.",
  ["Reconozco versos y estrofas.", "Sé separar una palabra en sílabas."],
  ["La rima es la repetición de sonidos al final de dos versos, a partir de la última vocal que lleva acento. En la rima consonante coinciden todas las letras: vocales y consonantes. Por ejemplo, «camino» y «destino» riman en -ino, y «luna» y «cuna» riman en -una.",
   "En la rima asonante coinciden solo las vocales. Por ejemplo, «casa» y «gata» tienen las vocales a-a, aunque las consonantes sean distintas. «Cielo» y «viento» riman en e-o. Cuando una palabra tiene dos vocales juntas, solo se considera la más fuerte: a, e, o.",
   "Para reconocer la rima, mira el final de los versos, di las palabras en voz alta y marca desde la última vocal acentuada. Si todo coincide, es consonante; si coinciden solo las vocales, es asonante; si no coinciden, no riman. No todos los poemas riman: hay poemas sin rima."],
  [("rima", "repetición de sonidos al final de dos versos"), ("rima consonante", "rima en que coinciden vocales y consonantes"), ("rima asonante", "rima en que coinciden solo las vocales"), ("vocal acentuada", "vocal que suena más fuerte en una palabra")],
  [("Rima consonante", "¿«Camino» y «destino» riman en consonante o en asonante?", ["Desde la vocal acentuada: camino → ino.", "Destino → ino.", "Coinciden vocales y consonantes: consonante."], "Consonante"),
   ("Rima asonante", "¿«Casa» y «gata» riman en consonante o en asonante?", ["Casa → a-a.", "Gata → a-a.", "Las vocales coinciden, las consonantes no: asonante."], "Asonante")],
  [("Pensar que riman las palabras que empiezan igual.", "Se mira el comienzo.", "La rima se mira al final."), ("Confundir consonante y asonante.", "Se piensa que cualquier parecido es consonante.", "Consonante: todo igual desde la vocal acentuada; asonante: solo las vocales.")],
  ([E("¿Dónde se mira la rima: al comienzo o al final de los versos?", "Al final", "Se repiten sonidos al final del verso."),
    E("¿Riman «luna» y «cuna» en consonante?", "Sí", "Coinciden todas las letras desde la vocal acentuada: -una."),
    E("¿Qué letras coinciden en una rima asonante: solo las vocales o todas?", "Solo las vocales", "Esa es la diferencia con la consonante.")],
   [E("«Mano» y «hermano»: ¿consonante o asonante?", "Consonante", "Coinciden en -ano."),
    E("«Cielo» y «viento»: ¿consonante o asonante?", "Asonante", "Solo coinciden las vocales e-o."),
    E("«Mar» y «cantar»: ¿consonante o asonante?", "Consonante", "Coinciden en -ar.")],
   [E("«Barco» y «campo»: ¿consonante o asonante?", "Asonante", "Desde la vocal acentuada coinciden las vocales a-o, pero las consonantes son distintas."),
    E("«Corazón» y «canción»: ¿consonante o asonante?", "Consonante", "Coinciden en -ón."),
    E("«Sol» y «amor»: ¿qué vocal coincide?", "o", "Ambas tienen o como vocal acentuada.")],
   [E("Ana dice que «mesa» y «mesero» riman porque empiezan igual. ¿Tiene razón?", "No", "La rima se mira al final."),
    E("¿Pueden rimar dos palabras en asonante sin rimar en consonante?", "Sí", "Por ejemplo casa y gata.")],
   [E("Poema: «Con la luna en el camino / canta un grillo su destino». ¿Qué versos riman y cómo?", "Camino y destino; consonante", "Terminan en -ino."),
    E("Poema: «Un pájaro en la rama / canta bajo el sol; / el viento lo acompaña / y el mundo es canción.» ¿Rima asonante entre «rama» y «acompaña»?", "Sí", "Ambas tienen vocales a-a.")]),
  [E("Quieres escribir un verso que rime en consonante con «corazón». ¿Qué palabra sirve: «canción» o «luna»?", "Canción", "Termina igual: -ón.")],
  [E("En poesía, ¿qué es la rima?", "Repetición de sonidos al final de dos versos", "Se mide desde la vocal acentuada."),
   E("¿Qué coincide en la rima consonante?", "Vocales y consonantes", "Todo desde la vocal acentuada."),
   E("¿Todos los poemas riman?", "No", "Hay poemas sin rima.")],
  (f"Lee este poema: «{HUERTO}» Busca dos pares de versos que rimen en consonante y uno en asonante, y justifica con las letras que coinciden.", "Consonante: «anochecer» y «crecer» (-ecer); «cuidado» y «dorado» (-ado). Asonante: «plaza» y «ventana» (a-a; aunque son de estrofas distintas, sus finales coinciden solo en las vocales).", ["encuentra dos pares consonantes", "encuentra un par asonante", "justifica con las letras"], ["tres pares con justificación"], ["buscar por el comienzo", "no justificar"], "Lee los pares en voz alta y comprueba si suenan parecidos."),
  "Busca en un poema dos palabras que rimen y di si es consonante o asonante.",
  "Escribe dos versos que rimen en consonante y dos que rimen en asonante.")

L(OA5, 7,
  "Este cuaderno, lápiz y el poema escrito en esta clase.",
  "Aprenderé a analizar un poema completo, usando sentidos, estado de ánimo, personificación, comparación, versos, estrofas y rima.",
  ["Reconozco figuras poéticas.", "Cuento versos y estrofas.", "Distingo la rima consonante y asonante."],
  ["Para analizar un poema puedes seguir un orden. Primero, léelo dos veces en voz alta. Segundo, di de qué trata y qué estado de ánimo sugiere. Tercero, busca imágenes que apelan a los sentidos. Cuarto, identifica figuras: personificaciones y comparaciones, y explica qué muestran.",
   "Después, mira la forma: cuántos versos y estrofas tiene y si hay rima, y de qué tipo. Por último, junta todo en una explicación: cómo la forma y las figuras ayudan a transmitir lo que el poema quiere decir. No es necesario encontrar todo en cada poema: algunos tienen rima y otros no.",
   "Al escribir tu análisis, cita siempre el verso. Por ejemplo: «La personificación “la noche se duerme” muestra una noche tranquila». Esto demuestra que tus ideas se apoyan en el poema y no solo en tu impresión."],
  [("analizar", "examinar las partes de algo para comprenderlo"), ("citar", "copiar entre comillas lo que dice un texto"), ("forma del poema", "versos, estrofas y rima"), ("tema", "de qué trata un poema")],
  [("Analizar una figura", f"Poema: «{LLUVIA}» ¿Qué figura es «las gotas, como campanas»?", ["Veo «como».", "Une gotas y campanas.", "Es una comparación: ambas suenan."], "Comparación; ambas suenan"),
   ("Analizar la forma", "¿Cuántas estrofas y versos tiene el poema de la lluvia?", ["Busco //: hay una.", "Entonces hay 2 estrofas.", "Cada una tiene 4 versos: 8 versos."], "2 estrofas y 8 versos")],
  [("Dar solo una impresión general.", "Se dice «es lindo».", "Cita versos y explica las figuras."), ("Analizar solo la forma o solo el significado.", "Se elige lo más fácil.", "Une forma y significado.")],
  ([E(LLUVIA + " En el poema de la lluvia, ¿cuántas estrofas hay?", n_estrofas(LLUVIA), "Hay un // que separa dos grupos."),
    E(LLUVIA + " ¿Qué verbo propio de personas usa el primer verso para la lluvia?", "Teje", "Tejer es una acción humana."),
    E(LLUVIA + " ¿Qué estado de ánimo transmite: calma o miedo?", "Calma", "Habla de canción, silencio y sueño.")],
   [E("¿Qué sentido apela «una canción de cristal»: el oído o el gusto?", "El oído", "Una canción se escucha."),
    E("¿Qué figura es «El silencio se acurruca»?", "Personificación", "Acurrucarse es propio de personas."),
    E("¿Qué figura es «las gotas, como campanas»?", "Comparación", "Usa el nexo «como».")],
   [E(LLUVIA + " ¿Cuántos versos tiene todo el poema de la lluvia?", n_versos(LLUVIA), "Son dos estrofas de cuatro versos."),
    E("¿Qué palabras riman en asonante: «cristal» y «pasar» o «campanas» y «techo»?", "«cristal» y «pasar»", "Ambas tienen la vocal a como vocal acentuada."),
    E("«Lana» y «montaña» ¿riman en asonante o consonante?", "Asonante", "Coinciden las vocales a-a y no las consonantes.")],
   [E(LLUVIA + " Ana dice que el poema transmite miedo por la noche inmensa. Beto, que transmite calma porque «se duerme». ¿Quién se apoya mejor en el texto?", "Beto", "«Se duerme sobre la montaña» sugiere tranquilidad."),
    E(LLUVIA + " ¿Cómo ayuda la comparación «como campanas» al estado de ánimo: añade un sonido suave que invita a dormir o suena a susto?", "Añade un sonido suave que invita a dormir", "Se relaciona con «llaman al sueño a pasar».")],
   [E("¿Qué personificación muestra una noche tranquila: «la noche se duerme sobre la montaña» o «la lluvia teje»?", "«la noche se duerme sobre la montaña»", "Dormir sugiere calma."),
    E("¿Qué parte del análisis une la forma con el significado: decir que la rima suave refuerza la calma o contar solo los versos?", "Decir que la rima suave refuerza la calma", "Relaciona forma y sentido.")]),
  [E("Quieres analizar un poema nuevo. ¿Qué haces primero: leerlo en voz alta dos veces o buscar la rima en el último verso?", "Leerlo en voz alta dos veces", "Primero hay que comprenderlo.")],
  [E("¿Qué debes hacer al escribir un análisis?", "Citar versos", "Así se apoya en el poema."),
   E("¿La forma del poema incluye versos, estrofas y rima?", "Sí", "Son los elementos formales."),
   E("¿Todos los poemas riman?", "No", "Algunos no tienen rima.")],
  (f"Analiza este poema: «{LLUVIA}» Escribe: 1) el tema y el estado de ánimo; 2) un verso que apele a un sentido; 3) una personificación y una comparación con su significado; 4) estrofas, versos y rima.", "1) Una noche de lluvia tranquila; calma. 2) «canción de cristal» (oído). 3) «El silencio se acurruca» muestra un silencio cálido; «las gotas, como campanas» destaca el sonido. 4) 2 estrofas, 8 versos; rima asonante entre cristal–pasar y lana–montaña.", ["responde los cuatro puntos", "cita versos", "relaciona forma y significado"], ["análisis escrito"], ["no citar", "dar solo impresiones"], "Subraya en el poema cada verso que citaste."),
  "Analiza un poema de tu libro de lectura siguiendo el orden de la clase.",
  "Escribe un poema de ocho versos con una personificación, una comparación y rima asonante, y analízalo.")
